use std::{
    path::{Path, PathBuf},
    sync::OnceLock,
};

use serde_json::Value;

/// Deployment configuration, generated by Nix at `/etc/maia/config.json`.
pub const DEPLOYMENT_CONFIG: &str = "/etc/maia/config.json";

/// Per-user secrets the desktop Settings form writes: the sync API key, model
/// keys and feed credentials. Never anything Nix renders, so merging the two is
/// unambiguous.
///
/// The deployment file may name it (`overlay_file`), which is how the NixOS
/// module's `xdg.configHome` reaches a service that has no XDG environment;
/// this is the fallback for a checkout.
pub fn overlay_config_path() -> PathBuf {
    let base = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
        // XDG_CONFIG_HOME is unset more often than it is set, and a relative
        // value is not meaningful here.
        .unwrap_or_else(|| match std::env::var("HOME") {
            Ok(home) if !home.is_empty() => PathBuf::from(home).join(".config"),
            _ => PathBuf::from(".config"),
        });
    base.join("maia").join("config.json")
}

/// Configuration file used when nothing else applies: the checkout's `maia.json`,
/// which is what `cargo tauri dev` and a bare `maia serve` rely on.
pub const CHECKOUT_CONFIG: &str = "maia.json";

/// The port the API listens on unless configured otherwise.
///
/// Kept in one place because the desktop app, the server and the NixOS module
/// all need to agree on it, and a mismatch is otherwise only visible as a
/// connection failure on the phone.
pub const DEFAULT_PORT: u16 = 3030;

/// A directory the server polls for statement files.
#[derive(Clone, Debug)]
pub struct WatchDir {
    pub path: PathBuf,
    /// `credit_agricole`, `firstrade`, …; parsed by the statements module.
    pub source: String,
}

/// Trading 212 feed settings. Credentials live in the per-user overlay; the
/// deployment file owns whether the feed runs and which environment it talks
/// to.
#[derive(Clone, Debug)]
pub struct T212FeedConfig {
    pub enabled: bool,
    pub environment: String,
    pub api_key: String,
    pub api_secret: String,
    pub lookback_days: i64,
}

impl Default for T212FeedConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            environment: "live".to_string(),
            api_key: String::new(),
            api_secret: String::new(),
            lookback_days: 90,
        }
    }
}

/// Periodic FX rate pull. The server is the only writer of `fx_rates`, so
/// this is what keeps statement imports from failing on a missing rate.
/// Deployment-owned: the service is what makes the outbound calls.
#[derive(Clone, Debug)]
pub struct FxConfig {
    pub enabled: bool,
    pub interval_hours: u64,
    /// Frankfurter-compatible API root (`{base_url}/{start}..{end}?base=..&symbols=..`).
    pub base_url: String,
}

impl FxConfig {
    pub const DEFAULT_BASE_URL: &str = "https://api.frankfurter.dev/v1";

    fn enabled() -> Self {
        Self {
            enabled: true,
            interval_hours: 6,
            base_url: Self::DEFAULT_BASE_URL.to_string(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Config {
    pub bind_addr: String,
    pub db_path: PathBuf,
    pub api_key: String,
    /// Saved models, keys joined in from the overlay. Order is the config's.
    pub models: Vec<ai::ModelSpec>,
    /// Which models serve which task, in fallback order.
    pub tasks: ModelTasks,
    /// Where exercise images and videos are read from, serving `GET /media/*`.
    ///
    /// `None` falls back to `<db_dir>/exercise_media`, which is what a checkout
    /// with the database beside the media wants.
    pub media_dir: Option<PathBuf>,
    /// Where the exercise catalogue is seeded from on first boot, looked for as
    /// `<dir>/parsed`. `None` disables seeding.
    ///
    /// Separate from [`Config::media_dir`] because seeding reads from the
    /// checkout while media is served from wherever the deployment put it.
    pub seed_dir: Option<PathBuf>,
    /// Where the desktop app writes markdown notes.
    pub notes_dir: Option<PathBuf>,
    /// Where receipt images are moved when a receipt is archived.
    ///
    /// This is a deployment setting rather than something the desktop app
    /// decides for itself: archiving moves files on disk, and the server is
    /// what performs that move, so it has to be a path both sides agree on
    /// without either guessing from its own working directory.
    pub archive_dir: Option<PathBuf>,
    /// Currency statement imports resolve foreign amounts into. Stored on the
    /// draft transaction alongside the original amount and rate.
    pub base_currency: String,
    /// Where the server keeps a copy of every statement input it parses.
    ///
    /// `None` means `<db_dir>/statements`, beside the database it describes.
    /// Watched files do not land here — their original moves to the parsed
    /// tree — but feed documents (which have no filename to honor) still do.
    pub statements_store_dir: Option<PathBuf>,
    /// Roots of the statement lifecycle. Files are dropped into
    /// `<dump>/<source>/`, the subfolder name picks the parser, and the file
    /// then lives wherever the state of its statements says it belongs:
    /// `<staged>/` while entries await review, `<parsed>/` once they are all
    /// imported or skipped, `<discarded>/` once they are all deleted, or
    /// `<failed>/<source>/` beside a `<name>.log` when the parse never
    /// succeeded.
    ///
    /// `parsed/` used to mean "did not crash", which is not the same thing as
    /// accepted — a rejected file sat there looking imported. The placement is
    /// derived from the database now (see `statements::watch::reconcile_files`)
    /// rather than written by whichever event last touched the file.
    ///
    /// All five default under the user's XDG data directory, and the
    /// deployment file may set them explicitly so the Nix module can create
    /// and grant them.
    pub statements_dump_dir: Option<PathBuf>,
    pub statements_staged_dir: Option<PathBuf>,
    pub statements_parsed_dir: Option<PathBuf>,
    pub statements_discarded_dir: Option<PathBuf>,
    pub statements_failed_dir: Option<PathBuf>,
    /// A directory of the user's own that the service drains into the dump
    /// tree — `~/Downloads`, say, where exports actually land.
    ///
    /// Unlike the four lifecycle roots this one is **overlay-owned**: the
    /// service only ever reads and moves *out of* it and never parses in
    /// place, so pointing it at a directory the user also uses for other
    /// things stays safe. `None` disables the drain.
    pub statements_intake_dir: Option<PathBuf>,
    /// Trading 212 feed. Credentials in here come from the overlay only.
    pub t212: T212FeedConfig,
    pub fx: FxConfig,
    /// The `pdftotext` (poppler) binary Firstrade PDF statements are read
    /// with. `None` means whatever `pdftotext` is on `PATH`.
    pub pdftotext_bin: Option<String>,
}

impl Config {
    pub fn new(db_path: PathBuf, api_key: String) -> Self {
        Self {
            bind_addr: format!("0.0.0.0:{DEFAULT_PORT}"),
            db_path,
            api_key,
            models: Vec::new(),
            tasks: ModelTasks::default(),
            media_dir: None,
            seed_dir: None,
            notes_dir: None,
            archive_dir: None,
            base_currency: "EUR".to_string(),
            statements_store_dir: None,
            statements_dump_dir: None,
            statements_staged_dir: None,
            statements_parsed_dir: None,
            statements_discarded_dir: None,
            statements_failed_dir: None,
            statements_intake_dir: None,
            t212: T212FeedConfig::default(),
            fx: FxConfig::enabled(),
            pdftotext_bin: None,
        }
    }

    pub fn with_bind_addr(mut self, addr: impl Into<String>) -> Self {
        self.bind_addr = addr.into();
        self
    }

    /// One Gemini model serving every task: what a test or a single-key
    /// checkout wants. An empty [key] leaves the tasks unassigned.
    pub fn with_model(mut self, key: impl Into<String>, name: impl Into<String>) -> Self {
        self.set_single_model(key.into(), name.into());
        self
    }

    fn set_single_model(&mut self, key: String, name: String) {
        let key = key.trim().to_string();
        self.models.retain(|m| m.id != LEGACY_MODEL_ID);
        self.tasks.receipt_ocr.retain(|id| id != LEGACY_MODEL_ID);
        self.tasks.receipt_matching.retain(|id| id != LEGACY_MODEL_ID);
        self.tasks.statement_extraction.retain(|id| id != LEGACY_MODEL_ID);
        if !key.is_empty() {
            self.models.push(ai::ModelSpec {
                id: LEGACY_MODEL_ID.to_string(),
                provider: ai::Provider::Gemini,
                base_url: None,
                model: name,
                api_key: key,
                vision: true,
            });
            self.tasks.receipt_ocr.push(LEGACY_MODEL_ID.to_string());
            self.tasks.receipt_matching.push(LEGACY_MODEL_ID.to_string());
            self.tasks.statement_extraction.push(LEGACY_MODEL_ID.to_string());
        }
    }

    pub fn with_media_dir(mut self, dir: Option<PathBuf>) -> Self {
        self.media_dir = dir;
        self
    }

    pub fn with_seed_dir(mut self, dir: Option<PathBuf>) -> Self {
        self.seed_dir = dir;
        self
    }

    pub fn with_archive_dir(mut self, dir: Option<PathBuf>) -> Self {
        self.archive_dir = dir;
        self
    }

    pub fn with_db_path(mut self, path: PathBuf) -> Self {
        self.db_path = path;
        self
    }

    /// Directory receipt images are moved into when archived.
    ///
    /// Defaults to `<db_dir>/receipts_archive`, which keeps the archive beside
    /// the database it describes rather than in whatever directory a process
    /// happened to be started from.
    pub fn archive_dir(&self) -> PathBuf {
        self.archive_dir.clone().unwrap_or_else(|| {
            self.db_path
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join("receipts_archive")
        })
    }

    /// True when at least one model can serve receipt OCR.
    pub fn ocr_enabled(&self) -> bool {
        !self.receipt_ocr_chain().is_empty()
    }

    /// The fallback chain for reading receipt images. Only vision models.
    pub fn receipt_ocr_chain(&self) -> ai::ModelChain {
        self.chain(&self.tasks.receipt_ocr, true)
    }

    /// The fallback chain for receipt-to-transaction matching assists.
    pub fn receipt_matching_chain(&self) -> ai::ModelChain {
        self.chain(&self.tasks.receipt_matching, false)
    }

    /// The fallback chain for reading statement activity out of PDF text.
    pub fn statement_extraction_chain(&self) -> ai::ModelChain {
        self.chain(&self.tasks.statement_extraction, false)
    }

    /// Builds a chain from task [ids], skipping (and logging) any id with no
    /// saved model, and any non-vision model when [vision] is required. The
    /// Nix module asserts both, so a skip here means a hand-edited file.
    fn chain(&self, ids: &[String], vision: bool) -> ai::ModelChain {
        let models = ids
            .iter()
            .filter_map(|id| {
                let Some(spec) = self.models.iter().find(|m| &m.id == id) else {
                    tracing::warn!(%id, "task names a model that is not configured; skipped");
                    return None;
                };
                if vision && !spec.vision {
                    tracing::warn!(%id, "model is not vision-capable; skipped for OCR");
                    return None;
                }
                Some(ai::Model::from_spec(spec))
            })
            .collect();
        ai::ModelChain::new(models)
    }

    /// Directory the server stores raw statement copies under.
    ///
    /// Defaults to `<db_dir>/statements`, which keeps them beside the database
    /// and inside the writable state directory rather than in the checkout.
    pub fn statements_store_dir(&self) -> PathBuf {
        self.statements_store_dir.clone().unwrap_or_else(|| {
            self.db_path
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join("statements")
        })
    }

    /// The user's XDG data directory, for the statement lifecycle default.
    ///
    /// An absolute `XDG_DATA_HOME` is honored; a relative one is not
    /// meaningful, exactly as in [`overlay_config_path`].
    pub fn xdg_data_home() -> PathBuf {
        let base = std::env::var("XDG_DATA_HOME")
            .ok()
            .map(PathBuf::from)
            .filter(|p| p.is_absolute())
            .unwrap_or_else(|| match std::env::var("HOME") {
                Ok(home) if !home.is_empty() => PathBuf::from(home).join(".local/share"),
                _ => PathBuf::from(".local/share"),
            });
        base
    }

    /// Statement lifecycle roots. All three default as siblings beneath
    /// `<XDG data home>/maia/statements`, so the personal exports live in the
    /// user's own data directory rather than in the deployment's state
    /// directory.
    pub fn statements_dump_dir(&self) -> PathBuf {
        self.statements_dump_dir
            .clone()
            .unwrap_or_else(|| Self::xdg_data_home().join("maia/statements/dump"))
    }

    /// Sibling of the dump root, e.g. `<dump>/../parsed`. This keeps the
    /// lifecycle in one tree even when only the dump folder is configured.
    fn statements_sibling(&self, configured: Option<&PathBuf>, name: &str) -> PathBuf {
        configured.cloned().unwrap_or_else(|| {
            self.statements_dump_dir()
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join(name)
        })
    }

    /// Parsed, awaiting review. A file sits here while any of its statements
    /// still has a pending entry.
    pub fn statements_staged_dir(&self) -> PathBuf {
        self.statements_sibling(self.statements_staged_dir.as_ref(), "staged")
    }

    /// Imported. Every statement of the file has been accepted or skipped —
    /// `parsed/` means the entries are in the ledger, not merely that the
    /// parser did not crash.
    pub fn statements_parsed_dir(&self) -> PathBuf {
        self.statements_sibling(self.statements_parsed_dir.as_ref(), "parsed")
    }

    /// Rejected. Every statement of the file was deleted without being
    /// accepted. The file is kept, not unlinked: dropping it back in is how a
    /// statement dismissed by mistake is recovered.
    pub fn statements_discarded_dir(&self) -> PathBuf {
        self.statements_sibling(self.statements_discarded_dir.as_ref(), "discarded")
    }

    /// Never parsed. Owned by `park`, and the one root with no statement rows
    /// behind it.
    pub fn statements_failed_dir(&self) -> PathBuf {
        self.statements_sibling(self.statements_failed_dir.as_ref(), "failed")
    }

    /// The user's own drop folder, drained into the dump tree. No default:
    /// unset means the feature is off, because guessing a directory the
    /// service would then move files out of is not a guess to make.
    pub fn statements_intake_dir(&self) -> Option<PathBuf> {
        self.statements_intake_dir.clone()
    }

    /// Directory holding exercise images and videos for `GET /media/*`.
    ///
    /// Defaults to `<db_dir>/exercise_media`.
    pub fn media_dir(&self) -> PathBuf {
        self.media_dir.clone().unwrap_or_else(|| {
            self.db_path
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join("exercise_media")
        })
    }

    /// The port parsed out of `bind_addr`.
    pub fn port(&self) -> u16 {
        self.bind_addr
            .rsplit(':')
            .next()
            .and_then(|p| p.trim().parse().ok())
            .unwrap_or(DEFAULT_PORT)
    }

    /// Reads the deployment file named by [explicit], else `/etc/maia/config.json`,
    /// else the checkout's `maia.json`, then merges the per-user overlay on top.
    ///
    /// A missing file is not an error: a fresh checkout has neither, and the
    /// defaults below suit it. A malformed file *is* an error, because silently
    /// falling back to a default database or a default API key would be worse.
    pub fn load(explicit: Option<&Path>) -> anyhow::Result<Self> {
        let merged = Self::read_deployment(explicit)?;
        // Best effort: the overlay is optional, and its absence is normal for a
        // server that has no desktop half.
        let overlay = read_object(&overlay_path_from(&merged)).unwrap_or_default();
        Ok(Self::from_values(merged, overlay))
    }

    /// The deployment file [explicit] names, else `/etc/maia/config.json`,
    /// else the checkout's `maia.json`, if any exists.
    pub fn deployment_path(explicit: Option<&Path>) -> Option<PathBuf> {
        match explicit {
            Some(path) => Some(path.to_path_buf()),
            None => [DEPLOYMENT_CONFIG, CHECKOUT_CONFIG]
                .into_iter()
                .map(PathBuf::from)
                .find(|p| p.exists()),
        }
    }

    /// The raw deployment object, read fresh: what the desktop Settings screen
    /// compares its pending edits against, since the cached [`Config::shared`]
    /// predates any rebuild that happened while the app was open.
    pub fn read_deployment(explicit: Option<&Path>) -> anyhow::Result<serde_json::Map<String, Value>> {
        match Self::deployment_path(explicit) {
            Some(path) => read_object(&path),
            None => Ok(serde_json::Map::new()),
        }
    }

    /// Process-wide configuration, loaded once.
    ///
    /// Both the server binary and the desktop app need it before any command can
    /// run, and re-reading on each call would make a partial write show up as
    /// inconsistent behaviour within a single request.
    pub fn shared(explicit: Option<&Path>) -> anyhow::Result<&'static Self> {
        static CACHE: OnceLock<anyhow::Result<Config>> = OnceLock::new();
        CACHE
            .get_or_init(|| Self::load(explicit.map(Path::new)))
            .as_ref()
            .map_err(|e| anyhow::anyhow!("{e}"))
    }

    /// Builds a configuration from a deployment object plus a desktop overlay.
    ///
    /// Split out from [`Config::load`] so the precedence rules can be tested
    /// without touching the filesystem.
    pub fn from_values(
        deployment: serde_json::Map<String, Value>,
        overlay: serde_json::Map<String, Value>,
    ) -> Self {
        let get = |map: &serde_json::Map<String, Value>, key: &str| -> Option<String> {
            map.get(key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .map(str::to_owned)
        };

        let db_path = get(&deployment, "database")
            .or_else(|| get(&overlay, "database"))
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("maia.db"));

        // A secret: the overlay owns it. The deployment value is still read as
        // a fallback so a host keeps answering between upgrading and moving
        // the key into Settings; the module no longer renders one.
        let mut cfg = Self::new(
            db_path,
            get(&overlay, "api_key")
                .or_else(|| get(&deployment, "api_key"))
                .unwrap_or_else(|| "fitfat-sync-key".into()),
        );

        if let Some(addr) = get(&deployment, "bind_addr") {
            cfg = cfg.with_bind_addr(addr);
        }
        read_models(&mut cfg, &deployment, &overlay);

        cfg.media_dir = get(&deployment, "media_dir").map(PathBuf::from);
        cfg.seed_dir = get(&deployment, "seed_dir").map(PathBuf::from);
        cfg.notes_dir = get(&deployment, "notes_dir")
            .or_else(|| get(&overlay, "notes_dir"))
            .map(PathBuf::from);
        // Deployment-owned, like the database path: the archive holds files the
        // server moves, so a per-user overlay must not be able to redirect it.
        cfg.archive_dir = get(&deployment, "archive_dir").map(PathBuf::from);

        // Also deployment-owned: the currency drafts are stored in, the
        // directory raw inputs are copied to, and the directories polled for
        // new files are all things the service acts on.
        cfg.base_currency = get(&deployment, "base_currency")
            .map(|value| value.to_uppercase())
            .unwrap_or_else(|| "EUR".to_string());
        cfg.statements_store_dir = get(&deployment, "statements_store_dir").map(PathBuf::from);

        let statements = deployment.get("statements").and_then(Value::as_object);
        // The lifecycle roots are deployment-owned for the same reason as the
        // store and the archive: the service reads, moves and grants access to
        // these paths, so a per-user overlay must not redirect them.
        let statement_path = |key: &str| -> Option<PathBuf> {
            statements
                .and_then(|statements| statements.get(key))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
        };
        cfg.statements_dump_dir = statement_path("dump_dir");
        cfg.statements_staged_dir = statement_path("staged_dir");
        cfg.statements_parsed_dir = statement_path("parsed_dir");
        cfg.statements_discarded_dir = statement_path("discarded_dir");
        cfg.statements_failed_dir = statement_path("failed_dir");

        // Deployment-owned like everything else that is not a secret: the
        // Settings form edits it through the Nix settings file, not the overlay.
        cfg.statements_intake_dir = statement_path("intake_dir");

        // Feed behaviour is deployment-owned; credentials come from the overlay
        // only, because the deployment file is readable by the whole system.
        let deployment_feed = statements
            .and_then(|statements| statements.get("feeds"))
            .and_then(Value::as_object)
            .and_then(|feeds| feeds.get("trading212"))
            .and_then(Value::as_object);
        let overlay_feed = overlay
            .get("statements")
            .and_then(Value::as_object)
            .and_then(|statements| statements.get("feeds"))
            .and_then(Value::as_object)
            .and_then(|feeds| feeds.get("trading212"))
            .and_then(Value::as_object);
        let feed_value = |key: &str| deployment_feed.and_then(|feed| feed.get(key));
        if let Some(enabled) = feed_value("enabled").and_then(Value::as_bool) {
            cfg.t212.enabled = enabled;
        }
        if let Some(environment) = feed_value("environment").and_then(Value::as_str) {
            cfg.t212.environment = if environment == "demo" {
                "demo"
            } else {
                "live"
            }
            .to_string();
        }
        if let Some(days) = feed_value("lookback_days").and_then(Value::as_i64) {
            cfg.t212.lookback_days = days.clamp(1, 3650);
        }
        if let Some(key) = overlay_feed
            .and_then(|feed| feed.get("api_key"))
            .and_then(Value::as_str)
        {
            cfg.t212.api_key = key.trim().to_string();
        }
        if let Some(secret) = overlay_feed
            .and_then(|feed| feed.get("api_secret"))
            .and_then(Value::as_str)
        {
            cfg.t212.api_secret = secret.trim().to_string();
        }

        // FX pull: deployment-owned, like the base currency it converts into.
        if let Some(fx) = deployment.get("fx").and_then(Value::as_object) {
            if let Some(enabled) = fx.get("enabled").and_then(Value::as_bool) {
                cfg.fx.enabled = enabled;
            }
            if let Some(hours) = fx.get("interval_hours").and_then(Value::as_u64) {
                cfg.fx.interval_hours = hours.clamp(1, 24 * 7);
            }
            if let Some(url) = fx
                .get("base_url")
                .and_then(Value::as_str)
                .map(|url| url.trim().trim_end_matches('/'))
                .filter(|url| !url.is_empty())
            {
                cfg.fx.base_url = url.to_string();
            }
        }
        cfg.pdftotext_bin = get(&deployment, "pdftotext_bin");
        cfg
    }

    /// The `pdftotext` command to run.
    pub fn pdftotext_bin(&self) -> &str {
        self.pdftotext_bin.as_deref().unwrap_or("pdftotext")
    }
}

/// Reads the overlay at [path], applies [update] and writes it back.
///
/// Write-then-rename so a crash cannot leave a half-written file that the next
/// start would reject, and owner-only because it holds every secret.
pub fn update_overlay(
    path: &Path,
    update: impl FnOnce(&mut serde_json::Map<String, Value>),
) -> anyhow::Result<()> {
    let mut root = read_object(path)?;
    update(&mut root);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let temp = path.with_extension("json.tmp");
    std::fs::write(&temp, serde_json::to_vec_pretty(&Value::Object(root))?)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&temp, std::fs::Permissions::from_mode(0o600))?;
    }
    std::fs::rename(&temp, path)?;
    Ok(())
}

/// The id a pre-`models` configuration's single key is filed under.
pub const LEGACY_MODEL_ID: &str = "default";

/// Which saved models serve which task, in fallback order.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ModelTasks {
    pub receipt_ocr: Vec<String>,
    pub receipt_matching: Vec<String>,
    pub statement_extraction: Vec<String>,
}

/// Where the overlay lives for this deployment: named by the deployment file
/// when the Nix module rendered one, else the XDG default.
pub fn overlay_path_from(deployment: &serde_json::Map<String, Value>) -> PathBuf {
    deployment
        .get("overlay_file")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|p| !p.is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(overlay_config_path)
}

/// Reads `models` and `tasks` from the deployment file and joins each model's
/// key from the overlay's `models.<id>.api_key`.
///
/// A deployment with no `models` but the old `model_api`/`model_name` pair
/// still works: it becomes one Gemini model, [`LEGACY_MODEL_ID`], on both
/// tasks, so a host keeps reading receipts across the upgrade.
fn read_models(
    cfg: &mut Config,
    deployment: &serde_json::Map<String, Value>,
    overlay: &serde_json::Map<String, Value>,
) {
    let text = |value: Option<&Value>| {
        value
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|v| !v.is_empty())
            .map(str::to_owned)
    };
    let overlay_models = overlay.get("models").and_then(Value::as_object);
    let key_for = |id: &str| {
        text(
            overlay_models
                .and_then(|models| models.get(id))
                .and_then(Value::as_object)
                .and_then(|model| model.get("api_key")),
        )
        .unwrap_or_default()
    };

    let Some(models) = deployment.get("models").and_then(Value::as_object) else {
        let key = text(overlay.get("model_api"))
            .or_else(|| text(deployment.get("model_api")))
            .unwrap_or_default();
        let name = text(deployment.get("model_name")).unwrap_or_else(|| "gemini-2.5-flash".into());
        cfg.set_single_model(key, name);
        return;
    };

    for (id, model) in models {
        let Some(model) = model.as_object() else {
            tracing::warn!(%id, "model entry is not an object; skipped");
            continue;
        };
        let provider_text = text(model.get("provider")).unwrap_or_else(|| "gemini".into());
        let Some(provider) = ai::Provider::parse(&provider_text) else {
            tracing::warn!(%id, provider = %provider_text, "unknown model provider; skipped");
            continue;
        };
        let Some(name) = text(model.get("model")) else {
            tracing::warn!(%id, "model entry has no `model`; skipped");
            continue;
        };
        cfg.models.push(ai::ModelSpec {
            id: id.clone(),
            provider,
            base_url: text(model.get("base_url")),
            model: name,
            api_key: key_for(id),
            vision: model.get("vision").and_then(Value::as_bool).unwrap_or(false),
        });
    }

    let tasks = deployment.get("tasks").and_then(Value::as_object);
    let ids = |key: &str| -> Vec<String> {
        tasks
            .and_then(|tasks| tasks.get(key))
            .and_then(Value::as_array)
            .map(|ids| ids.iter().filter_map(|id| text(Some(id))).collect())
            .unwrap_or_default()
    };
    cfg.tasks = ModelTasks {
        receipt_ocr: ids("receipt_ocr"),
        receipt_matching: ids("receipt_matching"),
        statement_extraction: ids("statement_extraction"),
    };
}

/// Reads a JSON object from [path], treating "does not exist" as absent.
///
/// A parse failure is surfaced: a config file with a typo in it should stop the
/// service, not leave it listening with a default API key.
fn read_object(path: &Path) -> anyhow::Result<serde_json::Map<String, Value>> {
    let text = match std::fs::read_to_string(path) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(serde_json::Map::new()),
        Err(e) => return Err(anyhow::anyhow!("reading {}: {e}", path.display())),
    };
    if text.trim().is_empty() {
        return Ok(serde_json::Map::new());
    }
    let value: Value = serde_json::from_str(&text)
        .map_err(|e| anyhow::anyhow!("parsing {}: {e}", path.display()))?;
    match value {
        Value::Object(map) => Ok(map),
        other => Err(anyhow::anyhow!(
            "{} must contain a JSON object, found {}",
            path.display(),
            kind_of(&other)
        )),
    }
}

fn kind_of(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
        Value::Object(_) => "an object",
    }
}

impl Default for Config {
    /// An in-memory database on an ephemeral port, for tests.
    fn default() -> Self {
        Self {
            bind_addr: "0.0.0.0:0".to_string(),
            db_path: PathBuf::from(":memory:"),
            api_key: "test-key".to_string(),
            models: Vec::new(),
            tasks: ModelTasks::default(),
            media_dir: None,
            seed_dir: None,
            notes_dir: None,
            archive_dir: None,
            base_currency: "EUR".to_string(),
            statements_store_dir: None,
            statements_dump_dir: None,
            statements_staged_dir: None,
            statements_parsed_dir: None,
            statements_discarded_dir: None,
            statements_failed_dir: None,
            statements_intake_dir: None,
            t212: T212FeedConfig::default(),
            // Tests never reach the network: the puller stays off unless a
            // test turns it on against a local stub.
            fx: FxConfig { enabled: false, ..FxConfig::enabled() },
            pdftotext_bin: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn obj(value: Value) -> serde_json::Map<String, Value> {
        value.as_object().unwrap().clone()
    }

    #[test]
    fn empty_input_yields_checkout_defaults() {
        let cfg = Config::from_values(serde_json::Map::new(), serde_json::Map::new());
        assert_eq!(cfg.db_path, PathBuf::from("maia.db"));
        assert_eq!(cfg.bind_addr, "0.0.0.0:3030");
        assert_eq!(cfg.api_key, "fitfat-sync-key");
        assert_eq!(cfg.media_dir(), PathBuf::from("exercise_media"));
        assert!(cfg.notes_dir.is_none());
        assert!(!cfg.ocr_enabled());
    }

    #[test]
    fn deployment_keys_are_all_honoured() {
        let cfg = Config::from_values(
            obj(json!({
                "database": "/var/lib/maia/maia.db",
                "bind_addr": "0.0.0.0:8080",
                "media_dir": "/srv/media",
                "seed_dir": "/srv/data",
                "notes_dir": "/var/lib/maia/notes",
                "api_key": "from-file",
                "model_api": "  gemini-key  ",
                "model_name": "gemini-2.5-pro",
            })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.db_path, PathBuf::from("/var/lib/maia/maia.db"));
        assert_eq!(cfg.port(), 8080);
        assert_eq!(cfg.api_key, "from-file");
        assert_eq!(cfg.media_dir(), PathBuf::from("/srv/media"));
        assert_eq!(cfg.seed_dir, Some(PathBuf::from("/srv/data")));
        assert_eq!(cfg.notes_dir, Some(PathBuf::from("/var/lib/maia/notes")));
        // A pre-`models` deployment becomes one Gemini model on every task.
        assert_eq!(cfg.models.len(), 1);
        assert_eq!(cfg.models[0].id, LEGACY_MODEL_ID);
        assert_eq!(cfg.models[0].api_key, "gemini-key");
        assert_eq!(cfg.models[0].model, "gemini-2.5-pro");
        assert!(cfg.ocr_enabled());
        assert!(!cfg.receipt_matching_chain().is_empty());
        assert!(!cfg.statement_extraction_chain().is_empty());
    }

    #[test]
    fn overlay_cannot_override_deployment_keys() {
        // The overlay owns secrets only; it must not be able to redirect the
        // database.
        let cfg = Config::from_values(
            obj(json!({ "database": "/var/lib/maia/maia.db" })),
            obj(json!({
                "database": "/tmp/hijacked.db",
                "receipts_path": "/home/lucas/receipts",
                "nutriments_path": "/home/lucas/nutriments",
            })),
        );
        assert_eq!(cfg.db_path, PathBuf::from("/var/lib/maia/maia.db"));
    }

    /// The sync key is a secret, so the overlay owns it. A deployment value is
    /// read only while a host has not moved its key into Settings yet.
    #[test]
    fn sync_api_key_comes_from_the_overlay_first() {
        let both = Config::from_values(
            obj(json!({ "api_key": "legacy" })),
            obj(json!({ "api_key": "  from-settings  " })),
        );
        assert_eq!(both.api_key, "from-settings");
        let legacy = Config::from_values(obj(json!({ "api_key": "legacy" })), serde_json::Map::new());
        assert_eq!(legacy.api_key, "legacy");
    }

    #[test]
    fn models_and_tasks_are_read_with_keys_from_the_overlay() {
        let cfg = Config::from_values(
            obj(json!({
                "models": {
                    "gemini-flash": { "provider": "gemini", "model": "gemini-2.5-flash", "vision": true },
                    "local": { "provider": "openai", "base_url": "http://localhost:11434/v1", "model": "qwen2.5vl:7b", "vision": true },
                    "text-only": { "provider": "openai", "model": "gpt-4.1-mini" },
                    "typo": { "provider": "anthropic-ish", "model": "x" }
                },
                "tasks": {
                    "receipt_ocr": ["local", "text-only", "missing", "gemini-flash"],
                    "receipt_matching": ["text-only", "gemini-flash"],
                    "statement_extraction": []
                },
                // Ignored once `models` exists.
                "model_api": "legacy-key"
            })),
            obj(json!({ "models": { "gemini-flash": { "api_key": " g-key " }, "text-only": { "api_key": "o-key" } } })),
        );
        let ids: Vec<&str> = cfg.models.iter().map(|m| m.id.as_str()).collect();
        assert_eq!(ids, ["gemini-flash", "local", "text-only"], "an unknown provider is skipped");
        let by_id = |id: &str| cfg.models.iter().find(|m| m.id == id).unwrap();
        assert_eq!(by_id("gemini-flash").api_key, "g-key");
        assert_eq!(by_id("local").api_key, "", "no key is fine for a local endpoint");
        assert_eq!(by_id("local").provider, ai::Provider::OpenAi);
        assert_eq!(by_id("local").base_url.as_deref(), Some("http://localhost:11434/v1"));

        let chain_ids = |chain: ai::ModelChain| -> Vec<String> {
            chain.models().iter().map(|m| m.id().to_string()).collect()
        };
        assert_eq!(
            chain_ids(cfg.receipt_ocr_chain()),
            ["local", "gemini-flash"],
            "OCR skips a non-vision model and an unknown id, keeping the order"
        );
        assert_eq!(chain_ids(cfg.receipt_matching_chain()), ["text-only", "gemini-flash"]);
        assert!(cfg.statement_extraction_chain().is_empty());
    }

    #[test]
    fn the_deployment_file_can_name_the_overlay() {
        let named = obj(json!({ "overlay_file": "/home/someone/.cfg/maia/config.json" }));
        assert_eq!(overlay_path_from(&named), PathBuf::from("/home/someone/.cfg/maia/config.json"));
        assert_eq!(overlay_path_from(&serde_json::Map::new()), overlay_config_path());
    }

    #[test]
    fn blank_strings_fall_through_to_defaults() {
        let cfg = Config::from_values(
            obj(json!({
                "database": "",
                "api_key": "   ",
                "media_dir": "",
                "bind_addr": "",
            })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.db_path, PathBuf::from("maia.db"));
        assert_eq!(cfg.api_key, "fitfat-sync-key");
        assert_eq!(cfg.media_dir, None);
        assert_eq!(cfg.bind_addr, "0.0.0.0:3030");
    }

    #[test]
    fn model_name_without_a_key_leaves_ocr_disabled() {
        let cfg = Config::from_values(
            obj(json!({ "model_name": "gemini-2.5-pro" })),
            serde_json::Map::new(),
        );
        assert!(cfg.models.is_empty());
        assert!(
            !cfg.ocr_enabled(),
            "without a key OCR must stay off rather than always fail"
        );
    }

    #[test]
    fn malformed_config_is_an_error() {
        let dir = std::env::temp_dir().join(format!("maia-cfg-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("config.json");
        std::fs::write(&path, "{ not json").unwrap();
        let err = read_object(&path).unwrap_err().to_string();
        assert!(err.contains("parsing"), "unhelpful error: {err}");

        // A JSON array is valid JSON but not a usable config.
        std::fs::write(&path, "[]").unwrap();
        let err = read_object(&path).unwrap_err().to_string();
        assert!(err.contains("must contain a JSON object"), "got: {err}");

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn missing_file_is_absent_not_an_error() {
        let path = std::path::Path::new("/nonexistent/maia/config.json");
        assert!(read_object(path).unwrap().is_empty());
    }

    #[test]
    fn port_parsing_survives_odd_bind_addrs() {
        let base = Config::new(PathBuf::from("x"), "k".into());
        assert_eq!(base.port(), DEFAULT_PORT);
        assert_eq!(base.clone().with_bind_addr("[::]:9999").port(), 9999);
        // Unparseable input falls back rather than panicking at startup.
        assert_eq!(base.with_bind_addr("nonsense").port(), DEFAULT_PORT);
    }

    /// The archive lives beside the database unless the deployment says
    /// otherwise, so it does not depend on the working directory of whichever
    /// process moved a file.
    #[test]
    fn archive_dir_defaults_beside_the_database() {
        let cfg = Config::new(PathBuf::from("/var/lib/maia/maia.db"), "k".into());
        assert_eq!(
            cfg.archive_dir(),
            PathBuf::from("/var/lib/maia/receipts_archive")
        );

        let configured = cfg.with_archive_dir(Some(PathBuf::from("/srv/archive")));
        assert_eq!(configured.archive_dir(), PathBuf::from("/srv/archive"));
    }

    /// The overlay must not be able to redirect the archive: it holds files the
    /// server moves, so it is owned by the deployment like the database path.
    #[test]
    fn archive_dir_ignores_the_user_overlay() {
        let cfg = Config::from_values(
            obj(json!({ "archive_dir": "/var/lib/maia/receipts_archive" })),
            obj(json!({ "archive_dir": "/tmp/hijacked" })),
        );
        assert_eq!(
            cfg.archive_dir(),
            PathBuf::from("/var/lib/maia/receipts_archive")
        );
    }

    #[test]
    fn statements_settings_come_from_the_deployment_file() {
        let cfg = Config::from_values(
            obj(json!({
                "base_currency": "usd",
                "statements": {
                    "dump_dir": "/mnt/statements/dump",
                    "parsed_dir": "/mnt/statements/parsed",
                    "failed_dir": "/mnt/statements/failed",
                    "feeds": {
                        "trading212": {
                            "enabled": true,
                            "environment": "demo",
                            "lookback_days": 30
                        }
                    }
                }
            })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.base_currency, "USD");
        assert_eq!(
            cfg.statements_dump_dir(),
            PathBuf::from("/mnt/statements/dump")
        );
        assert_eq!(
            cfg.statements_parsed_dir(),
            PathBuf::from("/mnt/statements/parsed")
        );
        assert_eq!(
            cfg.statements_failed_dir(),
            PathBuf::from("/mnt/statements/failed")
        );
        assert!(cfg.t212.enabled);
        assert_eq!(cfg.t212.environment, "demo");
        assert_eq!(cfg.t212.lookback_days, 30);
    }

    /// The parsed and failed trees default as siblings of the dump root, so a
    /// configured dump folder keeps the whole lifecycle in one place.
    #[test]
    fn statement_lifecycle_dirs_default_beside_the_dump_root() {
        // Both sides of each comparison resolve the XDG base the same way, so
        // the assertion holds whatever the test host has exported.
        let root = Config::xdg_data_home().join("maia/statements");
        let cfg = Config::from_values(serde_json::Map::new(), serde_json::Map::new());
        assert_eq!(cfg.statements_dump_dir(), root.join("dump"));
        assert_eq!(cfg.statements_parsed_dir(), root.join("parsed"));
        assert_eq!(cfg.statements_failed_dir(), root.join("failed"));

        // Only the dump folder configured: the siblings derive from it.
        let cfg = Config::from_values(
            obj(json!({ "statements": { "dump_dir": "/mnt/statements/dump" } })),
            serde_json::Map::new(),
        );
        assert_eq!(
            cfg.statements_parsed_dir(),
            PathBuf::from("/mnt/statements/parsed")
        );
        assert_eq!(
            cfg.statements_failed_dir(),
            PathBuf::from("/mnt/statements/failed")
        );
    }

    /// Credentials are per-user: the deployment file is read by the service
    /// manager and must never be where an API secret lives.
    #[test]
    fn feed_credentials_are_read_from_the_overlay_only() {
        let cfg = Config::from_values(
            obj(json!({
                "statements": {
                    "feeds": {
                        "trading212": { "enabled": true, "api_key": "from-deployment" }
                    }
                }
            })),
            obj(json!({
                "statements": {
                    "feeds": {
                        "trading212": {
                            "api_key": "  overlay-key  ",
                            "api_secret": "overlay-secret"
                        }
                    }
                }
            })),
        );
        assert!(
            cfg.t212.enabled,
            "deployment still owns whether the feed runs"
        );
        assert_eq!(cfg.t212.api_key, "overlay-key");
        assert_eq!(cfg.t212.api_secret, "overlay-secret");
    }

    #[test]
    fn statements_store_dir_defaults_beside_the_database() {
        let cfg = Config::new(PathBuf::from("/var/lib/maia/maia.db"), "k".into());
        assert_eq!(
            cfg.statements_store_dir(),
            PathBuf::from("/var/lib/maia/statements")
        );

        let configured = Config::from_values(
            obj(json!({ "statements_store_dir": "/srv/statements" })),
            serde_json::Map::new(),
        );
        assert_eq!(
            configured.statements_store_dir(),
            PathBuf::from("/srv/statements")
        );
    }

    /// The overlay owns the feed form, but not the paths the service opens.
    #[test]
    fn overlay_cannot_redirect_statement_paths() {
        let cfg = Config::from_values(
            obj(json!({
                "base_currency": "EUR",
                "statements": {
                    "dump_dir": "/srv/statements/dump"
                }
            })),
            obj(json!({
                "base_currency": "USD",
                "statements": {
                    "dump_dir": "/tmp/hijacked"
                }
            })),
        );
        assert_eq!(cfg.base_currency, "EUR");
        assert_eq!(
            cfg.statements_dump_dir(),
            PathBuf::from("/srv/statements/dump")
        );
    }
}
